import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"天山遁","description":"周易折中 - 天山遁","frontmatter":{"title":"天山遁","description":"周易折中 - 天山遁"},"headers":[],"relativePath":"classics/zhezhong/039.md","filePath":"classics/zhezhong/039.md"}'),h={name:"classics/zhezhong/039.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="天山遁" tabindex="-1">天山遁 <a class="header-anchor" href="#天山遁" aria-label="Permalink to “天山遁”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>遁序卦曰：恆者，乆也。物不可以乆居其所，故受之以遁。遁者，退也。夫乆則有去，相須之理也。遁所以繼恆也。遁，退也，避也，去之之謂也。為卦天下有山，天在上之物，陽性上進；山高起之物，形雖高起，體乃止物。有上陵之象，而止不進，天乃上進而去之，下陵而上去，是相違遁，故為遁去之義。二陰生於下，陰長將盛，陽消而退，小人漸盛，君子退而避之，故為遁也。</p><p>遁：亨，小利貞</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>遁，退避也。為卦二陰浸長，陽當退避，故為遁，六月之卦也。陽雖當遁，然九五當位而下有六二之應，若猶可以有為。但二陰浸長於下，則其勢不可以不遁，故其佔為：君子能遁，則身雖退而道亨；小人則利於守正，不可以浸長之故而遂侵迫於陽也。小謂陰柔小人也。此卦之佔與“否”之初二兩爻相類。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>遁者，陰長陽消，君子遁藏之時也。君子退藏以伸其道，道不屈則為亨，故遁所以有亨也。在事亦有由遁避而亨者，雖小人道長之時，君子知幾退避固善也。然事有不齊，與時消息，無必同也。陰柔方長而未至於甚盛，君子尚有遲遲致力之道，不可大貞而尚利小貞也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子易說 問：“遁，小利貞”。本義謂小人也。案易中“小”字，未有以為小人者，如“小利有攸往”與“小貞吉”之類，皆大小之“小”耳？ 曰：經文固無此例，以彖傳推之，則是指小人而言。今當且依經而存傳耳。</p></li><li><p>問：“遁，小利貞”。本義謂小人也。案易中“小”字，未有以為小人者，如“小利有攸往”與“小貞吉”之類，皆大小之“小”耳？ 曰：經文固無此例，以彖傳推之，則是指小人而言。今當且依經而存傳耳。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>“小利貞”之義，傳義說各不同。據易例，則似傳說為長。蓋至於三陰之否，則直曰“不利君子貞矣”。遁猶未至於否，但當遜避以善處之，不可過甚以激成其勢，故曰“小利貞”也。</p><p>象曰：天下有山，遁；君子以遠小人，不惡而嚴</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>天體無窮，山高有限，遁之象也。嚴者，君子自守之常，而小人自不能近。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>天下有山，山下起而乃正，天上進而相違，是遁避之象也。君子觀其象，以避遠乎小人。遠小人之道，若以惡聲厲色，適足以致其怨忿；惟在乎矜莊威嚴，使知敬畏，則自然遠矣。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>石氏介曰：不惡而嚴，外順而內正也。尚惡則小人憎，不嚴則正道消。</p></li><li><p>張子曰：“惡”讀為憎惡之“惡”。遠小人不可示以惡，惡則患及之，又焉能遠？嚴之為言，敬小人而遠之之意也。</p></li><li><p>楊氏時曰：天下有山，其藏疾也無所拒，然亦終莫之陵也。此君子遠小人不惡而嚴之象也。</p></li><li><p>郭氏雍曰：君子當遁之時，畏小人之害，志在遠之而已。遠之之道何如？不惡其人而嚴其分是也。孔子曰：“疾之已甚，亂也。”不惡則不疾矣。</p></li><li><p>俞氏琰曰：君子觀象以遠小人，豈有他哉？不過危行言遜而已。遜其言則不惡，不使之怨也；危其行則有不可犯之嚴，不使之不遜也。此君子遠小人之道也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>天下有山，以山喻小人，以天喻君子，似未切。蓋天下有山，山之高峻極於天也。山之高峻者，未嘗絕人，而自不可攀躋，故有不惡而嚴之象。楊氏之說，蓋是此意。</p><p>彖曰：遁亨，遁而亨也。剛當位而應，與時行也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以九五一爻釋亨義。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>小人道長之時，君子遁退，乃其道之亨也。君子遁藏，所以伸道也。此言處遁之道，自“剛當位而應”以下，則論時與卦才，尚有可為之理也。雖遁之時，君子處之，未有必遁之義。五以剛陽之德，處中正之位，又下與六二以中正相應，雖陰長之時，如卦之才，尚當隨時消息，苟可以致其力，無不至誠自盡以扶持其道，未必於遁藏而不為，故曰“與時行也”。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰：此釋遁之所以得亨通之義。小人之道方長，君子非遁不通，故曰“遁而亨也”。又曰釋所以能遁而致亨之由，良由九五以剛而當其位，有應於二，非為否亢。遁不否亢，即是相時而動，所以遁而得亨。</p></li><li><p>郭氏忠孝曰：聖人進退皆道，無入而不自得，雖遁亦亨也。與時行者，時止則止，時行則行，是為遁之義也。</p></li><li><p>朱子語類 問：“遁亨，遁而亨也，分明是說能遁便亨，更說‘剛當位而應，與時行也’是如何？”曰：“此其所以遁而亨也。陰方㣲為他，剛當位而應，所以能知時而遁，是能與時行。不然，便是與時背也。”</p></li><li><p>吳氏曰慎曰：非以剛當位而應，猶可亨，惟其當位而應，能順時而遁，所以亨也。與時行，謂時當遁而遁。</p></li></ul><p>小利貞，浸而長也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以下二陰釋小利貞。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>胡氏瑗曰：君子所以不得大有為於世，而惟小利於貞者，蓋以下之群陰浸長，而小人之黨漸盛也。</p></li><li><p>朱氏震曰：二陰浸長，方之於否，不利君子貞，固有閒矣。然不可大貞，利小貞而已。先儒謂居小官幹小事，其害未甚，我志猶行。蓋遁非疾世避俗，長往不反之謂也。去留遲速，惟時而已。非不忘乎君，不離乎群。消息盈虛，循天而行者，豈能盡遁之時義？</p></li><li><p>張氏清子曰：二陽為臨，二陰為遁。遁者，臨之反對也。臨之《彖》曰：“剛浸而長”，遁之《彖》則不曰“柔浸而長”，而止曰“浸而長”。</p></li></ul><p>遁之時義大矣哉</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>陰方浸長，處之為難，故其時義為尤大也。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>當陰長之時，不可大貞而尚小利貞者，蓋陰長必以浸漸，未能遽盛。君子尚可小貞其道，所謂小利貞，扶持使未遂亡也。遁者，陰之始長。君子知㣲，故當深戒。而聖人之意，未便遽已也，故有與時行小利貞之教。聖賢之於天下，雖知道之將廢，豈肯坐視其亂而不救？必區區致力於未極之閒，強此之衰，艱彼之進。其暫安苟得，為之孔孟之所屑為也。王允、謝安之於漢晉是也。若有可變之道，可亨之理，更不假言也。此處遁時之道也，故聖人贊其時義大矣哉。或久或速，其義皆大也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li>郭氏雍曰：遁之小利貞，睽之小事吉。不知者遂以為小而不思也。故孔子明其大，而後知小利貞、小事吉者，有大用存焉。</li></ul><p>初六：遁尾，厲，勿用有攸往</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>遁而在後，尾之象，危之道也。佔者不可以有所往，但晦處靜俟，可免災耳。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>它卦以下為初，遁者往遁也。在前者先進，故初乃為尾，尾在後之物也。遁而在後，不及者是也，是以危也。初以柔處㣲（注：此處可能是“內”的誤寫或特定術語），既已後矣，不可往也，往則危矣。㣲者易於晦藏，往既有危，不若不往之無災也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>陸氏績曰：陰氣已至於二，而初在其後，故曰遁尾也。避難當在前，而在後，故厲。往則與災難會，故勿用有攸往。</p></li><li><p>孔氏穎達曰：遁尾厲者，為遁之尾，最在後遁者也。小人長於內，應出外以避之，而最在卦內，是遁之為後，故曰遁尾厲也。危厲既至，則當危行言遜，勿用更有所往。</p></li><li><p>朱子語類 問：“遁尾厲，勿用有攸往”者，言不可有所往，但當晦處靜俟耳。此意如何？ 曰：程傳作不可往，謂不可去也。言遁已後矣，不可往，往則危。往既危，不若不往之無災。某竊以為不然。遁而在後，尾也，既已危矣，豈可更不往乎？若作佔辭看，尤分明。</p></li><li><p>問：“遁尾厲，勿用有攸往”者，言不可有所往，但當晦處靜俟耳。此意如何？ 曰：程傳作不可往，謂不可去也。言遁已後矣，不可往，往則危。往既危，不若不往之無災。某竊以為不然。遁而在後，尾也，既已危矣，豈可更不往乎？若作佔辭看，尤分明。</p></li><li><p>王氏申子曰：遁往遁也，故遁以初為後。在前者見幾先遁，初柔而不能決，止而不能行，故遁而在後，危厲之象也。既已處後，然位居卑下，不往即遁也。若又有所進往，則危厲益甚矣。</p></li><li><p>楊氏啟新曰：卦中以二陰為小人，至爻中則均退避之君子。蓋皆遁爻，則發遁義也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><ul><li><p>問：易例多取初爻為居先，何獨遁而取在後之義？ 曰：因卦義而變者也。初於序則先，然於位則內也。遁者，遠出之義也，故以外卦為善。初居最內，豈非在後者乎？</p></li><li><p>問：明夷之初九居內，何以為先幾乎？ 曰：明夷則以上卦為內，以上六為主，故也。是以六四入左腹，而六五當內難也。如是，則初又為最遠，與遁之義正相反也。</p></li></ul><p>象曰：遁尾之厲，不往何災也</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>見幾先遁，固為善也。遁而為尾，危之道也。往既有危，不若不往而晦藏，可免於災。處危故也。古人處微下隱，亂世而不去者多矣。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>程傳以不遁為免災，朱子以晦處勿有所行為免災。故朱子嘗欲劾韓侂冑，佔得此爻而止。</p><p>六二：執之用黃牛之革，莫之勝說</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>以中順自守，人莫能解，必遁之志也。佔者固守亦當如是。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>二與五為正應，雖在相違遁之時，二以中正順應於五，五以中正親合於二，其交自固。黃中色，牛順物，革堅固之物。二五以中正順道相與，其固如執系之以牛革也。莫之勝說，謂其交之固，不可勝言也。在遁之時，故極言之。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>呉氏綺曰：六二居人臣之位，任國家之責，不當遁者也。故六二不言遁。</p></li><li><p>龔氏煥曰：五爻皆言遁，惟六二不言者，二上與五應，雖當遁時，固結而不可遁者也。故有“執用黃牛之革”之象，謂其有必遁之志，似未必然。</p></li><li><p>蔡氏清曰：就隱遁上說，如何見是中順？蓋收斂其德不形於外，不危言激論，不矯矯伸節，惟知自守而已。此之謂中順。</p></li><li><p>孔氏穎達曰：處中居內，非遁之人也。既非遁之人，便為所遁之主。物皆棄已而遁，何以執固留之？惟有中和厚順之道，可以固而安之也。能用此道，則無能勝已解脫而去。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>此爻傳義說亦不同，吳氏、龔氏則暢程傳之說，謂六二為五正應，如肺腑之臣，義不可去，箕子所謂“我不顧行遁”是也。蔡氏則申本義之說，謂處遁以中順之道，如所謂“危行言遜”者，亦與不惡而嚴之義合。至孔氏則別為一說，謂其能羈縻善類而不使去，執如《雅詩》“執我仇讎”之執。於經文“執之”兩字，語氣亦自恰合也。故並存其說。</p><p>象曰：執用黃牛，固志也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>上下以中順之道相固結，其心志甚堅，如執之以牛革也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>侯氏行果曰：上應貴主，志在輔時，不隨物遁，獨守中直，堅如革束。執此之志，莫之勝。說殷之父師當此爻矣。</p></li><li><p>蔡氏淸曰：謂自固其志，不可榮以祿也。</p></li></ul><h3 id="附錄" tabindex="-1">附錄 <a class="header-anchor" href="#附錄" aria-label="Permalink to “附錄”">​</a></h3><ul><li>孔氏穎達曰：固志者，堅固遁者之志，使不去己也。</li></ul><p>九三：系遁，有疾厲，畜臣妾吉</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>下比二陰，當遁而有所繫之象，有疾而危之道也。然以畜臣妾則吉，蓋君子之於小人，惟臣妾則不必其賢而可畜耳，故其佔如此。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>陽志說陰，三與二切比，系乎二者也。遁貴速而遠，有所繫累，則安能速且遠也？害於遁矣，故為有疾也。遁而不速，是以危也。臣妾，小人女子，懷恩而不知義，親愛之則忠其上，繫戀之私恩，懷小人女子之道也。故以畜養臣妾則得其心為吉也。然君子之待小人，亦不如是也。三與二非正應，以暱比相親，非待君子之道。若以正則，雖系不得為有疾。蜀先主之不忍棄士民是也，雖危為無咎矣。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰：九三無應於上，與二相比，處遁之世而意有所繫，故曰“系遁”。遁之為義宜遠，小人既繫於陰，即是有疾憊而致危厲也。親於所近，系在於下，施之於人，畜養臣妾則可矣，大事則兇，故曰“畜臣妾吉”。</p></li><li><p>胡氏瑗曰：為遁之道在乎遠去。九三居內卦之上，切比六二之陰，不能超然遠遁，是有疾病而危厲者也。畜臣妾吉者，言九三既不能遠遁，然畜群小以臣妾之道，即得其吉。蓋臣妾至賤者也可以遠則遠之，可以近則近之，如此則吉可求也。</p></li><li><p>蘇氏浚曰：“畜臣妾吉”示之以待小人之道，見其不可系也。蓋小人之易親如臣妾之易以惑人，畜之法止有不惡而嚴，嚴以杜其狎侮之奸，而不惡以柔其忿戾之氣。用畜臣妾之法以畜之，庶可以免疾憊而吉耳。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>孔子曰：“惟女子與小人為難養也，近之則不遜，遠之則怨。”然則不遠不近之間，豈非不惡而嚴之義乎？故當遁之時，有所繫而未得去者，待小人以畜臣妾之道則可矣。胡氏、蘇氏說明白。</p><p>象曰：系遁之厲，有疾憊也；畜臣妾吉，不可大事也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>遁而有繫累，必以困憊致危。其有疾乃憊也，蓋力亦不足矣。以此暱愛之心畜養臣妾則吉，豈可以當大事乎？</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>張氏淸子曰：當遁而系，故有疾而厲，至於憊乏也。惟當以剛自守，止下二陰而畜之以臣妾之道，然後獲吉，又豈可當大事乎？</li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>不可大事，言未可直行其志，危言危行也，與彖“小貞吉”，大象“不惡而嚴”之意皆相貫。</p><p>九四：好遁，君子吉，小人否</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>下應初六而幹體剛健，有情好而能絕之以遁之象也。惟自克之君子能之，而小人不能，故佔者君子則吉而小人否也。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>四與初為正應，是所好愛者也。君子雖有所好愛，義苟當遁，則去而不疑，所謂克己復禮，以道制欲，是以吉也。小人則不能以義處，暱於所好，牽於所私，至於陷辱其身而不能自拔，故在小人則否也。否，不善也。四幹體能剛斷，聖人以其處陰而有系，故設小人之戒，恐其失於正也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰：有應於陰，不惡而嚴，故曰“好遁”。小人暗於事幾，不忿怒成仇，則私溺為慮矣。</p></li><li><p>朱氏震曰：好者，情之所好也。君子剛決以義斷之，舍所好而去，故吉；否者，不能然也。此爻與初六相應，處陰而有所繫，故陳小人之戒以佐君子之決。</p></li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><ul><li><p>好者，惡之反也。好遁言其不惡也，從容以遁而不為忿戾之行。孟子曰：“予豈若是小丈夫然哉？怒悻悻然見於其面。”正好遁之義也。小人否者，即孟子所謂小丈夫者也。</p></li><li><p>又案：君子吉，小人否。若以小人與君子相敵者言之，則“否”字解如泰否之義。謂好遁者身退道亨，在君子固吉矣，然豈小人之福哉？自古君子退避，則小人亦不旋踵而覆敗。是君子之遁者，非君子之兇，乃君子之吉；而致君子之遁者，非小人之泰，乃小人之否也。此義與《剝》上“小人剝廬”之指正同。蓋《易》雖不為小人謀，而未嘗不為小人戒也。本義以“小利貞”為戒小人之辭，似與此意亦合。</p></li></ul><p>象曰：君子好遁，小人否也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>君子雖有好而能遁，不失於義；小人則不能勝其私意而至於不善也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li>俞氏琰曰：爻辭雲“好遁君子吉，小人否”。爻傳不及“吉”字，蓋謂惟君子為能好遁，小人則不能好遁也。既好遁，則遁而亨其吉，不假言矣。</li></ul><p>九五：嘉遁，貞吉</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>剛陽中正，下應六二亦柔順而中正，遁之嘉美者也。佔者如是而正則吉矣。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>九五中正，遁之嘉美者也。處得中正之道，時止時行，乃所謂嘉美也。故為貞正而吉。九五非無系應，然與二皆以中正自處，是其心志及乎動止，莫非中正而無私系之失，所以為嘉也。在彖則概言遁時，故云“與時行小利貞”，尚有濟遁之意。於爻至五，遁將極矣，故惟以中正處遁言之。遁非人君之事故，不主君位言，然人君之所避遠，乃遁也，亦在中正而已。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li>龔氏煥曰：“嘉遁貞吉”，即彖傳所謂“遁而亨”也。五當位而應，與時偕行者也。</li></ul><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>此爻雖不主君位，然居尊則亦臣之位高者也。凡功成身退者，人臣之道。故伊尹曰：“臣罔以寵利居成功”，豈非遁之嘉美者乎？嘉之義，比好又優矣。</p><p>象曰：嘉遁貞吉，以正志也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>志正則動必由正，所以為遁之嘉也。居中得正而應中正，是其志正也，所以為吉。人之遁也，止也，唯在正其志而已矣。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li>張子曰：居正處中，能正其志，故獲貞吉。</li></ul><h3 id="案-9" tabindex="-1">案 <a class="header-anchor" href="#案-9" aria-label="Permalink to “案”">​</a></h3><p>君子之志不在寵利，故進以禮而退以義，所謂正志也。</p><p>上九：肥遁，無不利</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>以剛陽居卦外，下無系應，遁之遠而處之裕者也。故其象佔如此。肥者，寬裕自得之意。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>肥者，充大寬裕之意。遁者，惟飄然遠逝，無所繫滯之為善。上九幹體剛斷，在卦之外矣，又下無所繫，是遁之遠而無累，可謂寬裕有餘裕也。遁者，窮困之時也，善處則為肥矣。其遁如此，何所不利？</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：最處外極，無應於內，超然絕去，心無疑顧，憂患不能累，矰繳不能及，是以“肥遁無不利”也。</p></li><li><p>姜氏寶曰：四之“好”不如五之“嘉”，五之“嘉”不如上之“肥”。上與二陰無應無系，故肥。肥者，疾憊之反也。</p></li></ul><p>象曰：肥遁無不利，無所疑也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>其遁之遠，無所疑滯也。蓋在外則已遠，無應則無累，故為剛決無疑也。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>侯氏行果曰：最處外極，無應於內，心無疑戀，超世高舉，安時無悶，故肥遁無不利。</p></li><li><p>趙氏汝梅曰：四陽之中，三繫於陰，四五應於陰，皆不能不自疑。至上則疑慮盡亡，蓋無有不利者矣。</p></li><li><p>李氏心傳曰：無所疑也。此及升之九三並言之，此決於退，彼決於進，時之宜耳。</p></li></ul><p>總論</p><ul><li>項氏安世曰：下三爻艮也，主於止，故為不往、為執、革、為系遁。上三爻幹也，主於行，故為好遁、為嘉遁、為肥遁也。</li></ul>',130)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
